// The native importer accepts JPEG only. Route this extension's PNG artwork to
// its permission-checked importer, preserving the exact generated bytes.
const fluxThreeNativeRequest = genericRequest;
genericRequest = function(url, data, ...args) {
    if (url == 'AddNewPreset' && String(data?.param_map?.fluxkleinadvanced).toLowerCase() == 'true'
        && data?.preview_image?.startsWith('data:image/png;base64,')) {
        url = 'FluxKleinSavePngPreset';
    }
    return fluxThreeNativeRequest(url, data, ...args);
};

/** Whether a compat class is the native FLUX.3 Klein family: 'flux-3-image-klein' in current SwarmUI cores, 'flux-3-klein'
 * in cores before that rename. */
function isFluxThreeKleinCompat(compatClass) {
    return compatClass == 'flux-3-image-klein' || compatClass == 'flux-3-klein';
}

/** Keep the extension's controls scoped to the native FLUX.3 model family. */
let fluxThreeFeatureSeen = false;
featureSetChangers.push(() => {
    let flag = 'secourses_flux_three_klein';
    fluxThreeFeatureSeen ||= currentBackendFeatureSet.includes(flag);
    if (!fluxThreeFeatureSeen) {
        return [[], []];
    }
    return isFluxThreeKleinCompat(currentModelHelper?.curCompatClass) ? [[flag], []] : [[], [flag]];
});

/** A visual editor for the native FLUX.3 layout table plus sequential prompt batches. */
class FluxThreeKleinUI {
    constructor() {
        this.selected = 0;
        this.boxes = [];
        this.prompts = [];
        this.running = false;
        postParamBuildSteps.push(() => this.install());
        hideParamCallbacks.push(() => this.updateMode());
    }

    element(tag, className, text) {
        let elem = document.createElement(tag);
        elem.className = className || '';
        if (text != null) {
            elem.textContent = text;
        }
        return elem;
    }

    button(label, action, parent) {
        let button = this.element('button', 'btn btn-secondary flux-three-button', label);
        button.type = 'button';
        button.addEventListener('click', action);
        parent.appendChild(button);
        return button;
    }

    install() {
        this.input = document.getElementById('input_fluxkleinlayoutboxes');
        this.listInput = document.getElementById('input_fluxkleinpromptlist');
        this.mode = document.getElementById('input_fluxkleinmode');
        if (!this.input || !this.listInput || !this.mode || this.input.dataset.fluxThreeReady) {
            return;
        }
        this.input.dataset.fluxThreeReady = 'true';
        this.boxWrap = findParentOfClass(this.input, 'auto-input');
        this.layout = this.element('div', 'flux-three-layout');
        this.input.after(this.layout);
        this.input.classList.add('flux-three-json');
        this.input.hidden = true;
        this.layout.appendChild(this.element('p', 'flux-three-help', 'Draw a box, then describe it. Drag to move; drag the corner to resize. Cite <obj_1>, <obj_2> in your prompt.'));
        this.canvas = this.element('canvas', 'flux-three-canvas');
        this.canvas.tabIndex = 0;
        this.canvas.setAttribute('aria-label', 'FLUX.3 layout canvas. Draw with the mouse or use Add box and the coordinate fields.');
        this.layout.appendChild(this.canvas);
        let toolbar = this.element('div', 'flux-three-toolbar');
        this.layout.appendChild(toolbar);
        this.button('Add box', () => this.addBox(), toolbar);
        this.button('Delete box', () => this.deleteBox(), toolbar);
        this.button('Move up', () => this.moveBox(-1), toolbar);
        this.button('Move down', () => this.moveBox(1), toolbar);
        this.button('Show JSON', event => {
            this.input.hidden = !this.input.hidden;
            event.currentTarget.textContent = this.input.hidden ? 'Show JSON' : 'Hide JSON';
        }, toolbar);
        this.select = this.element('select', 'flux-three-select');
        this.select.setAttribute('aria-label', 'Selected layout box');
        this.select.addEventListener('change', () => {
            this.selected = Number(this.select.value);
            this.render();
        });
        this.layout.appendChild(this.select);
        this.fields = this.element('div', 'flux-three-fields');
        this.layout.appendChild(this.fields);
        this.description = this.element('textarea', 'flux-three-description');
        this.description.rows = 3;
        this.description.placeholder = 'Describe this object, including its color, shape and material.';
        this.description.setAttribute('aria-label', 'Layout object description');
        this.fields.appendChild(this.description);
        this.description.addEventListener('input', () => {
            if (this.boxes[this.selected]) {
                this.boxes[this.selected].desc = this.description.value;
                this.saveBoxes(false);
                this.labelSelected();
            }
        });
        let typeRow = this.element('div', 'flux-three-type-row');
        this.type = this.element('select', 'flux-three-select');
        this.type.setAttribute('aria-label', 'Layout box type');
        for (let [value, label] of [['obj', 'Object'], ['text', 'Text / lettering']]) {
            let option = this.element('option', '', label);
            option.value = value;
            this.type.appendChild(option);
        }
        this.type.addEventListener('change', () => {
            this.boxes[this.selected].type = this.type.value;
            this.saveBoxes();
        });
        this.lettering = this.element('input', 'flux-three-lettering');
        this.lettering.type = 'text';
        this.lettering.placeholder = 'Exact text to render';
        this.lettering.setAttribute('aria-label', 'Exact layout lettering');
        this.lettering.addEventListener('input', () => {
            this.boxes[this.selected].text = this.lettering.value;
            this.saveBoxes(false);
            this.labelSelected();
        });
        typeRow.append(this.type, this.lettering);
        this.fields.appendChild(typeRow);
        let coords = this.element('div', 'flux-three-coordinates');
        this.coordInputs = [];
        for (let [i, label] of ['Top %', 'Left %', 'Bottom %', 'Right %'].entries()) {
            let wrapper = this.element('label', '', label);
            let input = this.element('input', '');
            input.type = 'number';
            input.min = 0;
            input.max = 100;
            input.step = 0.1;
            input.setAttribute('aria-label', `Layout ${label}`);
            input.addEventListener('change', () => {
                let values = this.coordInputs.map(x => Number(x.value) / 100);
                if (values.some(x => !Number.isFinite(x) || x < 0 || x > 1) || values[0] >= values[2] || values[1] >= values[3]) {
                    this.error.textContent = 'Coordinates must be 0–100%, with bottom below top and right after left.';
                    return;
                }
                this.boxes[this.selected].bbox = values;
                this.saveBoxes();
            });
            this.coordInputs.push(input);
            wrapper.appendChild(input);
            coords.appendChild(wrapper);
        }
        this.fields.appendChild(coords);
        this.error = this.element('div', 'flux-three-error');
        this.error.setAttribute('role', 'status');
        this.layout.appendChild(this.error);
        this.input.addEventListener('change', () => {
            if (!this.saving) {
                this.readBoxes();
            }
        });
        this.mode.addEventListener('change', () => this.updateMode());
        for (let id of ['width', 'height', 'aspectratio', 'megapixels', 'sidelength']) {
            document.getElementById(`input_${id}`)?.addEventListener('change', () => this.renderSoon());
        }
        this.installPointer();
        this.installBatch();
        this.readBoxes();
        this.updateMode();
    }

    updateMode() {
        if (this.boxWrap && this.mode) {
            let enabled = document.getElementById('input_fluxkleinadvanced')?.checked;
            if (!enabled || this.mode.value != 'Layout / optional references' || !isFluxThreeKleinCompat(currentModelHelper?.curCompatClass)) {
                this.boxWrap.style.display = 'none';
            }
            else {
                this.boxWrap.style.display = '';
                this.render();
            }
        }
    }

    readBoxes() {
        try {
            let boxes = JSON.parse(this.input.value || '[]');
            if (!Array.isArray(boxes) || boxes.some(x => !Array.isArray(x.bbox) || x.bbox.length != 4
                || x.bbox.some(v => !Number.isFinite(v) || v < 0 || v > 1) || x.bbox[0] >= x.bbox[2] || x.bbox[1] >= x.bbox[3])) {
                throw new Error('Expected boxes with bbox: [top, left, bottom, right] coordinates from 0 to 1.');
            }
            this.boxes = boxes;
            this.selected = Math.max(0, Math.min(this.selected, boxes.length - 1));
            this.error.textContent = '';
            this.render();
        }
        catch (error) {
            this.error.textContent = `Layout JSON: ${error.message}`;
        }
    }

    saveBoxes(render = true) {
        this.saving = true;
        this.input.value = JSON.stringify(this.boxes);
        this.input.dispatchEvent(new Event('input', {bubbles: true}));
        this.input.dispatchEvent(new Event('change', {bubbles: true}));
        this.saving = false;
        this.error.textContent = '';
        if (render) {
            this.render();
        }
    }

    addBox() {
        if (this.boxes.length >= 32) {
            this.error.textContent = 'A layout can contain up to 32 boxes.';
            return;
        }
        let offset = (this.boxes.length % 5) * 0.08;
        this.boxes.push({type: 'obj', bbox: [0.1 + offset, 0.1 + offset, 0.45 + offset, 0.45 + offset], desc: ''});
        this.selected = this.boxes.length - 1;
        this.saveBoxes();
        this.description.focus();
    }

    deleteBox() {
        this.boxes.splice(this.selected, 1);
        this.selected = Math.max(0, Math.min(this.selected, this.boxes.length - 1));
        this.saveBoxes();
    }

    moveBox(delta) {
        let target = this.selected + delta;
        if (target < 0 || target >= this.boxes.length) {
            return;
        }
        [this.boxes[target], this.boxes[this.selected]] = [this.boxes[this.selected], this.boxes[target]];
        this.selected = target;
        this.saveBoxes();
    }

    /** While a width or height is typed, the size fields send a change per partial number ('1', '19', '192'), and a canvas
     * drawn for each collapsed to a sliver until the typing ended; the layout redraws once the size has been still. */
    renderSoon() {
        clearTimeout(this.renderTimer);
        this.renderTimer = setTimeout(() => this.render(), 400);
    }

    render() {
        if (!this.canvas) {
            return;
        }
        let width = Number(document.getElementById('input_width')?.value) || 1024;
        let height = Number(document.getElementById('input_height')?.value) || 1024;
        if (width < 64 || height < 64) {
            [width, height] = this.lastSize || [1024, 1024];
        }
        this.lastSize = [width, height];
        this.canvas.width = 960;
        this.canvas.height = Math.max(64, Math.round(960 * height / width));
        this.canvas.style.maxWidth = `${420 * width / height}px`;
        let c = this.canvas.getContext('2d');
        let w = this.canvas.width, h = this.canvas.height;
        c.fillStyle = '#f3f4f6';
        c.fillRect(0, 0, w, h);
        c.strokeStyle = '#d7dde5';
        c.lineWidth = 1;
        for (let n = 1; n < 10; n++) {
            c.beginPath(); c.moveTo(w * n / 10, 0); c.lineTo(w * n / 10, h); c.stroke();
            c.beginPath(); c.moveTo(0, h * n / 10); c.lineTo(w, h * n / 10); c.stroke();
        }
        for (let [i, box] of this.boxes.entries()) {
            let [top, left, bottom, right] = box.bbox;
            let color = ['#2563eb', '#c2410c', '#047857', '#7e22ce', '#be123c'][i % 5];
            c.fillStyle = `${color}25`;
            c.fillRect(left * w, top * h, (right - left) * w, (bottom - top) * h);
            c.strokeStyle = color;
            c.lineWidth = i == this.selected ? 7 : 3;
            c.strokeRect(left * w, top * h, (right - left) * w, (bottom - top) * h);
            c.font = 'bold 28px sans-serif';
            c.fillStyle = color;
            c.fillRect(left * w, top * h, 136, 40);
            c.fillStyle = 'white';
            c.fillText(`<obj_${i + 1}>`, left * w + 7, top * h + 29);
            if (i == this.selected) {
                c.fillStyle = color;
                c.fillRect(right * w - 13, bottom * h - 13, 26, 26);
            }
        }
        this.select.replaceChildren();
        for (let [i, box] of this.boxes.entries()) {
            let option = this.element('option', '', `<obj_${i + 1}> ${box.desc || box.text || 'Describe this box'}`);
            option.value = i;
            this.select.appendChild(option);
        }
        this.select.value = `${this.selected}`;
        this.fields.hidden = this.boxes.length == 0;
        this.select.hidden = this.boxes.length == 0;
        let box = this.boxes[this.selected];
        if (box) {
            // a focused description keeps what is being typed into it, but only for the box it belongs to: a click on
            // another box on the canvas leaves the focus in the text box, which then showed the previous box's words
            if (document.activeElement != this.description || this.descriptionBox !== this.selected) {
                this.description.value = box.desc || '';
            }
            this.descriptionBox = this.selected;
            this.type.value = box.type || 'obj';
            this.lettering.hidden = this.type.value != 'text';
            this.lettering.value = box.text || '';
            this.coordInputs.forEach((input, i) => input.value = +(box.bbox[i] * 100).toFixed(2));
        }
    }

    /** The box list's label for the selected box follows its description or lettering as it is typed (a full render, which
     * rebuilt the list, does not run on each keystroke). */
    labelSelected() {
        let box = this.boxes[this.selected], option = this.select.options[this.selected];
        if (box && option) {
            option.textContent = `<obj_${this.selected + 1}> ${box.desc || box.text || 'Describe this box'}`;
        }
    }

    installPointer() {
        let point = event => {
            let rect = this.canvas.getBoundingClientRect();
            return [Math.max(0, Math.min(1, (event.clientY - rect.top) / rect.height)),
                Math.max(0, Math.min(1, (event.clientX - rect.left) / rect.width))];
        };
        this.canvas.addEventListener('pointerdown', event => {
            if (event.button != 0) {
                return;
            }
            event.preventDefault();
            let [y, x] = point(event);
            let selected = this.boxes[this.selected];
            let handle = selected && Math.abs(x - selected.bbox[3]) < 0.04 && Math.abs(y - selected.bbox[2]) < 0.04;
            let hit = -1;
            for (let i = this.boxes.length - 1; i >= 0; i--) {
                let b = this.boxes[i].bbox;
                if (x >= b[1] && x <= b[3] && y >= b[0] && y <= b[2]) {
                    hit = i;
                    break;
                }
            }
            if (handle) {
                this.drag = {mode: 'resize', origin: [y, x], box: [...selected.bbox]};
            }
            else if (hit >= 0) {
                this.selected = hit;
                this.drag = {mode: 'move', origin: [y, x], box: [...this.boxes[hit].bbox]};
            }
            else if (this.boxes.length < 32) {
                this.boxes.push({type: 'obj', bbox: [y, x, Math.min(1, y + 0.002), Math.min(1, x + 0.002)], desc: ''});
                this.selected = this.boxes.length - 1;
                this.drag = {mode: 'draw', origin: [y, x]};
            }
            this.canvas.setPointerCapture(event.pointerId);
            this.render();
        });
        this.canvas.addEventListener('pointermove', event => {
            if (!this.drag) {
                return;
            }
            let [y, x] = point(event), [oy, ox] = this.drag.origin;
            let b = this.drag.box;
            if (this.drag.mode == 'draw') {
                this.boxes[this.selected].bbox = [Math.min(y, oy), Math.min(x, ox), Math.max(y, oy), Math.max(x, ox)];
            }
            else if (this.drag.mode == 'resize') {
                this.boxes[this.selected].bbox = [b[0], b[1], Math.max(b[0] + 0.01, y), Math.max(b[1] + 0.01, x)];
            }
            else {
                let dy = Math.max(-b[0], Math.min(1 - b[2], y - oy));
                let dx = Math.max(-b[1], Math.min(1 - b[3], x - ox));
                this.boxes[this.selected].bbox = [b[0] + dy, b[1] + dx, b[2] + dy, b[3] + dx];
            }
            this.render();
        });
        let finish = () => {
            if (!this.drag) {
                return;
            }
            let box = this.boxes[this.selected];
            if (this.drag.mode == 'draw' && (box.bbox[2] - box.bbox[0] < 0.01 || box.bbox[3] - box.bbox[1] < 0.01)) {
                this.boxes.splice(this.selected, 1);
                this.selected = Math.max(0, this.boxes.length - 1);
            }
            this.drag = null;
            this.saveBoxes();
        };
        this.canvas.addEventListener('pointerup', finish);
        this.canvas.addEventListener('pointercancel', finish);
        this.canvas.addEventListener('keydown', event => {
            let box = this.boxes[this.selected];
            if (!box) {
                return;
            }
            if (event.key == 'Delete') {
                event.preventDefault(); this.deleteBox(); return;
            }
            let directions = {ArrowUp: [-0.005, 0], ArrowDown: [0.005, 0], ArrowLeft: [0, -0.005], ArrowRight: [0, 0.005]};
            let d = directions[event.key];
            if (d) {
                event.preventDefault();
                let b = box.bbox;
                let dy = Math.max(-b[0], Math.min(1 - b[2], d[0]));
                let dx = Math.max(-b[1], Math.min(1 - b[3], d[1]));
                box.bbox = [b[0] + dy, b[1] + dx, b[2] + dy, b[3] + dx];
                this.saveBoxes();
            }
        });
    }

    installBatch() {
        this.listInput.hidden = true;
        this.batch = this.element('div', 'flux-three-batch');
        this.listInput.after(this.batch);
        this.batch.appendChild(this.element('p', 'flux-three-help', 'Generate a series with the same settings and references. The main prompt runs first, followed by these extra prompts. Each .txt file is one prompt.'));
        this.promptRows = this.element('div', 'flux-three-prompt-rows');
        this.batch.appendChild(this.promptRows);
        let toolbar = this.element('div', 'flux-three-toolbar');
        this.batch.appendChild(toolbar);
        this.button('Add prompt', () => {
            this.prompts.push({name: `Prompt ${this.prompts.length + 2}`, text: ''});
            this.savePrompts();
        }, toolbar);
        for (let folder of [false, true]) {
            let picker = this.element('input', '');
            picker.type = 'file'; picker.multiple = true; picker.accept = '.txt'; picker.hidden = true;
            picker.setAttribute('aria-label', folder ? 'Import prompt folder' : 'Import prompt text files');
            if (folder) {
                picker.setAttribute('webkitdirectory', '');
            }
            picker.addEventListener('change', async () => {
                let files = [...picker.files].filter(f => /\.txt$/i.test(f.name)).sort((a, b) => (a.webkitRelativePath || a.name).localeCompare(b.webkitRelativePath || b.name, undefined, {numeric: true}));
                if (files.length + this.prompts.length > 63) {
                    this.batchStatus.textContent = 'Import at most 63 extra prompts per batch.';
                    return;
                }
                for (let file of files) {
                    let text = (await file.text()).replace(/^\uFEFF/, '').trim();
                    if (text) {
                        this.prompts.push({name: file.name, text});
                    }
                }
                picker.value = '';
                this.savePrompts();
            });
            this.batch.appendChild(picker);
            this.button(folder ? 'Import folder' : 'Import .txt', () => picker.click(), toolbar);
        }
        this.button('Clear extra prompts', () => {
            this.prompts = []; this.savePrompts();
        }, toolbar);
        this.batchRun = this.button('Generate prompt batch', () => this.runBatch(), toolbar);
        this.batchRun.classList.replace('btn-secondary', 'btn-primary');
        this.batchStop = this.button('Stop after current', () => {
            this.stopRequested = true;
            this.batchStop.disabled = true;
            this.batchStatus.textContent = 'Stopping after the current prompt finishes.';
        }, toolbar);
        this.batchStop.disabled = true;
        this.batchStatus = this.element('div', 'flux-three-batch-status');
        this.batchStatus.setAttribute('role', 'status');
        this.batch.appendChild(this.batchStatus);
        this.listInput.addEventListener('change', () => {
            if (!this.savingPrompts) {
                this.readPrompts();
            }
        });
        this.readPrompts();
    }

    readPrompts() {
        try {
            let data = JSON.parse(this.listInput.value || '[]');
            if (!Array.isArray(data) || data.some(p => typeof p.text != 'string')) {
                throw new Error('Expected a list of prompts.');
            }
            this.prompts = data;
            this.renderPrompts();
        }
        catch (error) {
            this.batchStatus.textContent = `Prompt list: ${error.message}`;
        }
    }

    savePrompts(render = true) {
        this.savingPrompts = true;
        this.listInput.value = JSON.stringify(this.prompts);
        this.listInput.dispatchEvent(new Event('input', {bubbles: true}));
        this.listInput.dispatchEvent(new Event('change', {bubbles: true}));
        this.savingPrompts = false;
        if (render) {
            this.renderPrompts();
        }
    }

    renderPrompts() {
        this.promptRows.replaceChildren();
        for (let [i, prompt] of this.prompts.entries()) {
            let row = this.element('div', 'flux-three-prompt-row');
            row.appendChild(this.element('strong', '', prompt.name || `Prompt ${i + 2}`));
            let text = this.element('textarea', 'flux-three-description');
            text.value = prompt.text;
            text.rows = 3;
            text.setAttribute('aria-label', `Extra prompt ${i + 1}`);
            text.addEventListener('input', () => {
                prompt.text = text.value; this.savePrompts(false);
            });
            row.appendChild(text);
            this.button('Remove prompt', () => {
                this.prompts.splice(i, 1); this.savePrompts();
            }, row);
            this.promptRows.appendChild(row);
        }
    }

    async runBatch() {
        if (this.running) {
            return;
        }
        let captured = getGenInput();
        let prompts = [captured.prompt || '', ...this.prompts.map(p => p.text)].filter(p => p.trim());
        if (!captured.fluxkleinadvanced || !isFluxThreeKleinCompat(currentModelHelper?.curCompatClass) || !prompts.length || prompts.length > 64) {
            this.batchStatus.textContent = 'Select a FLUX.3 preset and enter between 1 and 64 prompts.';
            return;
        }
        // Reuse native progress, history and image display while isolating the batch's websocket.
        class PromptBatchHandler extends GenerateHandler {
            constructor() {
                super(); this.validateModel = false; this.first = true;
            }
            getGenInput() { return this.nextInput; }
            beforeGenRun() { num_waiting_gens += Number(this.nextInput.images || 1); }
            resetBatchIfNeeded() {
                if (this.first) { super.resetBatchIfNeeded(); this.first = false; }
            }
            hadError(message) {
                super.hadError(message);
                let reject = this.reject; this.resolve = this.reject = null;
                reject?.(new Error(message));
            }
            internalHandleData(...args) {
                super.internalHandleData(...args);
                if (args[0].socket_intention == 'close') {
                    let resolve = this.resolve; this.resolve = this.reject = null; resolve?.();
                }
            }
            one(input) {
                this.nextInput = input;
                return new Promise((resolve, reject) => {
                    this.resolve = resolve; this.reject = reject; this.doGenerate();
                });
            }
        }
        this.running = true;
        this.stopRequested = false;
        this.batchRun.disabled = true;
        this.batchStop.disabled = false;
        let handler = new PromptBatchHandler();
        let completed = 0;
        try {
            for (let prompt of prompts) {
                if (this.stopRequested) {
                    break;
                }
                this.batchStatus.textContent = `Generating prompt ${completed + 1} of ${prompts.length}…`;
                await handler.one({...captured, prompt});
                completed++;
            }
            this.batchStatus.textContent = `${this.stopRequested ? 'Stopped' : 'Complete'}: ${completed} of ${prompts.length} prompts generated.`;
        }
        catch (error) {
            this.batchStatus.textContent = `Batch stopped at prompt ${completed + 1}: ${error.message}`;
        }
        finally {
            this.running = false;
            this.batchRun.disabled = false;
            this.batchStop.disabled = true;
        }
    }
}

let fluxThreeKleinUI = new FluxThreeKleinUI();
